/**
 * 远程数据 Context
 *
 * 作用：
 * - App 启动时预取所有远程模块数据（data/*.json）
 * - 各数据 hook 通过 useRemoteDataStore 读取远程数据
 * - 前台页面展示时，远程数据优先于本地默认数据
 * - 后台管理页面不受影响，继续使用本地 localStorage 数据
 *
 * 为什么用 Context 而不是每个 hook 各自 fetch？
 * 1. 避免多个 hook 同时发起相同 fetch 请求
 * 2. 统一缓存机制（5 分钟 sessionStorage）
 * 3. 方便一键刷新所有远程数据
 *
 * 🔴 防闪烁设计：
 * - 首帧同步读取 sessionStorage 缓存（如果有 5 分钟内的缓存），避免首屏 fallback 数据 → 远程数据 的跳变
 * - 所有模块 fetch 完成后一次性 setState，避免 11 个模块逐个 setModules 导致 11 次全树重渲染
 * - Context value 用 useMemo 缓存，避免每次渲染生成新对象引用导致消费者级联重渲染
 * - fetch 失败的模块写入 failedModules 标记，后续不再重试（除非手动 refresh）
 * - 前台 preferRemote 模式：初始直接显示缓存数据（无 loading 态），远程数据到达后静默替换
 */

import { createContext, useContext, type ReactNode } from 'react';

export type RemoteDataModule =
  | 'products'
  | 'advantages'
  | 'testimonials'
  | 'features'
  | 'heroSlides'
  | 'about'
  | 'news'
  | 'categories'
  | 'footer'
  | 'seo'
  | 'privacy'
  | 'translations'
  | 'settings';

interface RemoteDataStoreValue {
  modules: Partial<Record<RemoteDataModule, unknown>>;
  loading: boolean;
  hasRemoteData: boolean;
  refreshModule: (module: RemoteDataModule) => Promise<void>;
  refreshAll: () => Promise<void>;
}

const RemoteDataStoreContext = createContext<RemoteDataStoreValue | null>(null);

/**
 * 极简空壳 RemoteDataProvider — V107 稳定版
 *
 * 不做任何 fetch、不读缓存、不设 loading、不触发重渲染。
 * 所有 useRemoteDataStore 调用都返回 null，各数据 hook 走本地默认数据路径。
 * 彻底消除远程数据导致的 hook 顺序错误和重渲染问题。
 */
export function RemoteDataProvider({ children }: { children: ReactNode }) {
  return (
    <RemoteDataStoreContext.Provider value={null}>
      {children}
    </RemoteDataStoreContext.Provider>
  );
}

/**
 * 读取指定模块的远程数据
 * @param module 模块名
 * @returns 远程数据（如果加载成功且存在），否则返回 null
 *
 * 🔴 重要：此函数内部不能有任何提前 return / 条件性调用，
 * 否则会破坏 React Hook 调用顺序，导致 "Should have a queue" 错误。
 */
export function useRemoteDataStore<T = unknown>(module: RemoteDataModule): T | null {
  const ctx = useContext(RemoteDataStoreContext);
  const data = ctx?.modules[module];
  return (data as T) ?? null;
}

/**
 * 读取完整的远程数据 store（用于刷新等操作）
 */
export function useRemoteDataStoreFull(): RemoteDataStoreValue | null {
  return useContext(RemoteDataStoreContext);
}

export default RemoteDataProvider;
